#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
#include <libpq-fe.h>

class PostgresConnection {
public:
    explicit PostgresConnection(const std::string& connectionInfo)
        : connection_(PQconnectdb(connectionInfo.c_str()), PQfinish) {
        if (!connection_) {
            throw std::runtime_error("Unable to allocate PostgreSQL connection.");
        }
        if (PQstatus(connection_.get()) != CONNECTION_OK) {
            std::string error = PQerrorMessage(connection_.get());
            throw std::runtime_error("PostgreSQL connection failed: " + error);
        }
    }

    PostgresConnection(const PostgresConnection&) = delete;
    PostgresConnection& operator=(const PostgresConnection&) = delete;
    PostgresConnection(PostgresConnection&&) noexcept = default;
    PostgresConnection& operator=(PostgresConnection&&) noexcept = default;

    PGconn* handle() const noexcept {
        return connection_.get();
    }

    bool ok() const noexcept {
        return connection_ && PQstatus(connection_.get()) == CONNECTION_OK;
    }

private:
    std::unique_ptr<PGconn, void (*)(PGconn*)> connection_;
};

PostgresConnection createPostgresConnection(const std::string& connectionInfo) {
    return PostgresConnection(connectionInfo);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <connection-string>\n";
        return 1;
    }

    try {
        PostgresConnection connection = createPostgresConnection(argv[1]);
        std::cout << "PostgreSQL connection created successfully.\n";
        return connection.ok() ? 0 : 1;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

